dosya.icerik:
-- siparisleri siparis tablosuna yukler (anahtarsiz tablo). Parametre: gun
\set dosya '/data/gelen/siparis_' :gun '.csv'
\set yukle '\\copy siparis_gecici from ' :'dosya' ' with (format csv, header true)'
:yukle
insert into siparis (id, gun, tutar) select id, :'gun', tutar from siparis_gecici;
insert into yukleme_log (dosya, satir) select 'siparis_' || :'gun' || '.csv', count(*) from siparis_gecici;
truncate siparis_gecici;
